void SpawnManagerPanel::New(const std::string&root){m_asset={};m_asset.header.id=engine::AssetHandle::Generate();m_asset.name="NewSpawnEncounter";m_asset.entries.push_back({"Enemy","Default","EnemyPrototype"});m_asset.waves.push_back({});m_path=(std::filesystem::path(root)/"GameAssets"/"Spawns"/"NewSpawnEncounter.3dgspawn").string();m_selectedEntry=m_selectedWave=0;m_dirty=true;m_status.clear();}
bool SpawnManagerPanel::SaveForShutdown(const std::string&root,std::string*error){if(m_path.empty())New(root);if(!engine::SaveSpawnAsset(m_path,m_asset,error))return false;m_dirty=false;return true;}
bool SpawnManagerPanel::PrefabCombo(const char*label,std::string&path,engine::AssetHandle&id,EditorAssets&assets){bool changed=false;const auto preview=path.empty()?std::string("Optional prefab dependency"):std::filesystem::path(path).filename().string();if(ImGui::BeginCombo(label,preview.c_str())){if(ImGui::Selectable("None",path.empty())){path.clear();id={};changed=true;}for(const auto&p:assets.ContentAssetPaths(EditorAssets::Type::Prefab)){ImGui::PushID(p.c_str());const auto name=std::filesystem::path(p).filename().string();if(ImGui::Selectable(name.c_str(),p==path)){path=p;id=assets.AssetIdForPath(p);changed=true;}ImGui::PopID();}ImGui::EndCombo();}return changed;}
void SpawnManagerPanel::DrawVolumePreview(){const ImVec2 size(std::max(ImGui::GetContentRegionAvail().x,160.f),190);ImGui::InvisibleButton("SpawnVolumePreview",size);auto*d=ImGui::GetWindowDrawList();const auto a=ImGui::GetItemRectMin(),b=ImGui::GetItemRectMax();d->AddRectFilled(a,b,IM_COL32(14,18,24,255));d->AddText({a.x+8,a.y+7},IM_COL32(210,220,235,255),"ENCOUNTER PREVIEW");const ImVec2 center{(a.x+b.x)*.5f,(a.y+b.y)*.5f+10};const ImU32 volume=IM_COL32(70,185,240,220);if(m_asset.shape==engine::SpawnShape::Box)d->AddRect({center.x-90,center.y-55},{center.x+90,center.y+55},volume,0.0f,ImDrawFlags_None,2.0f);else d->AddCircle(center,m_asset.shape==engine::SpawnShape::Point?8.f:65.f,volume,48,2.0f);std::unordered_map<std::string,float> weights;float total=0;for(const auto&e:m_asset.entries)if(m_previewDifficulty>=e.minimumDifficulty&&m_previewDifficulty<=e.maximumDifficulty){weights[e.name]+=e.weight;total+=e.weight;}float x=a.x+12;for(const auto&kv:weights){const float w=(b.x-a.x-24)*(total>0?kv.second/total:0);d->AddRectFilled({x,b.y-28},{x+w,b.y-10},IM_COL32(85,150,90,255));d->AddText({x+3,b.y-27},IM_COL32_WHITE,kv.first.c_str());x+=w;}if(m_previewPlaying){m_previewTime+=ImGui::GetIO().DeltaTime;const float angle=m_previewTime*2.5f;d->AddCircleFilled({center.x+std::cos(angle)*45,center.y+std::sin(angle)*35},5.0f,IM_COL32(255,180,55,255));}}
SpawnManagerPanel::Result SpawnManagerPanel::Draw(EditorAssets&assets,const std::string&root,bool*open){Result result;if(!m_asset.header.id.Valid())New(root);if(!m_pendingOpen.empty()){std::string e;if(engine::LoadSpawnAsset(m_pendingOpen,&m_asset,&e)){m_path=m_pendingOpen;m_dirty=false;m_selectedEntry=m_selectedWave=0;}else m_status=e;m_pendingOpen.clear();}if(!ImGui::Begin(EditorPanels::Name(EditorPanels::Panel::SpawnManager),open)){ImGui::End();return result;}if(ImGui::Button("New"))New(root);ImGui::SameLine();if(ImGui::Button("Save")){std::string e;if(engine::SaveSpawnAsset(m_path,m_asset,&e)){m_dirty=false;result.saved=true;result.message="Saved spawn encounter: "+m_path;}else result.message=e;}ImGui::SameLine();if(ImGui::Button("Apply to Selected"))result.applySelected=true;ImGui::SameLine();ImGui::TextUnformatted(m_path.c_str());m_dirty|=ImGui::InputText("Encounter Name",&m_asset.name);
if(ImGui::BeginTabBar("SpawnTabs")){if(ImGui::BeginTabItem("Volume & Rules")){int shape=static_cast<int>(m_asset.shape);m_dirty|=ImGui::Combo("Volume Shape",&shape,"Point\0Box\0Sphere\0");m_asset.shape=static_cast<engine::SpawnShape>(shape);if(m_asset.shape==engine::SpawnShape::Box)m_dirty|=ImGui::DragFloat3("Box Extents",&m_asset.boxExtents.x,.1f,.1f,1000.f);else{m_dirty|=ImGui::DragFloat("Radius",&m_asset.radius,.1f,.1f,1000.f);m_dirty|=ImGui::DragFloat("Half Height",&m_asset.height,.1f,0,1000.f);}m_dirty|=ImGui::Checkbox("Auto Start",&m_asset.autoStart);ImGui::SameLine();m_dirty|=ImGui::Checkbox("Player Enter Trigger",&m_asset.triggerOnPlayerEnter);m_dirty|=ImGui::Checkbox("One Shot",&m_asset.oneShot);ImGui::SameLine();m_dirty|=ImGui::Checkbox("Loop Waves",&m_asset.loopWaves);m_dirty|=ImGui::Checkbox("Random Yaw",&m_asset.randomYaw);ImGui::SameLine();m_dirty|=ImGui::Checkbox("Recycle Dead",&m_asset.recycleDead);m_dirty|=ImGui::DragInt("Maximum Concurrent",&m_asset.maximumConcurrent,1,1,10000);m_dirty|=ImGui::DragInt("Maximum Total",&m_asset.maximumTotal,1,1,100000);m_dirty|=ImGui::DragFloat("Retrigger Cooldown",&m_asset.retriggerCooldown,.1f,0,3600);int seed=static_cast<int>(m_asset.seed);m_dirty|=ImGui::InputInt("Random Seed",&seed);m_asset.seed=static_cast<std::uint32_t>(std::max(seed,1));ImGui::EndTabItem();}
if(ImGui::BeginTabItem("Weighted Groups")){if(ImGui::Button("Add Entry")){m_asset.entries.push_back({});m_selectedEntry=static_cast<int>(m_asset.entries.size())-1;m_dirty=true;}for(int i=0;i<static_cast<int>(m_asset.entries.size());++i){ImGui::PushID(i);auto&e=m_asset.entries[static_cast<std::size_t>(i)];if(ImGui::Selectable((e.name+"  ["+e.group+"]").c_str(),m_selectedEntry==i))m_selectedEntry=i;ImGui::SameLine();if(ImGui::SmallButton("X")){m_asset.entries.erase(m_asset.entries.begin()+i);m_selectedEntry=std::clamp(m_selectedEntry,0,std::max(0,static_cast<int>(m_asset.entries.size())-1));m_dirty=true;ImGui::PopID();break;}ImGui::PopID();}if(!m_asset.entries.empty()){auto&e=m_asset.entries[static_cast<std::size_t>(std::clamp(m_selectedEntry,0,static_cast<int>(m_asset.entries.size())-1))];ImGui::Separator();m_dirty|=ImGui::InputText("Display Name",&e.name);m_dirty|=ImGui::InputText("Group",&e.group);m_dirty|=ImGui::InputText("Scene Prototype Name",&e.prototypeName);m_dirty|=PrefabCombo("Prefab Dependency",e.prefabPath,e.prefabId,assets);m_dirty|=ImGui::DragFloat("Weight",&e.weight,.05f,0,10000);m_dirty|=ImGui::DragFloatRange2("Difficulty Range",&e.minimumDifficulty,&e.maximumDifficulty,.05f,0,10,"%.2f","%.2f");m_dirty|=ImGui::DragInt("Maximum Alive",&e.maximumAlive,1,1,10000);m_dirty|=ImGui::DragInt("Pool Limit",&e.poolLimit,1,0,10000);}ImGui::EndTabItem();}
if(ImGui::BeginTabItem("Waves")){if(ImGui::Button("Add Wave")){engine::SpawnWave w;w.name="Wave "+std::to_string(m_asset.waves.size()+1);m_asset.waves.push_back(w);m_selectedWave=static_cast<int>(m_asset.waves.size())-1;m_dirty=true;}for(int i=0;i<static_cast<int>(m_asset.waves.size());++i){ImGui::PushID(i);auto&w=m_asset.waves[static_cast<std::size_t>(i)];if(ImGui::Selectable((std::to_string(i+1)+". "+w.name).c_str(),m_selectedWave==i))m_selectedWave=i;ImGui::SameLine();if(ImGui::ArrowButton("up",ImGuiDir_Up)&&i>0){std::swap(m_asset.waves[i],m_asset.waves[i-1]);m_selectedWave=i-1;m_dirty=true;}ImGui::SameLine();if(ImGui::ArrowButton("down",ImGuiDir_Down)&&i+1<static_cast<int>(m_asset.waves.size())){std::swap(m_asset.waves[i],m_asset.waves[i+1]);m_selectedWave=i+1;m_dirty=true;}ImGui::SameLine();if(ImGui::SmallButton("X")){m_asset.waves.erase(m_asset.waves.begin()+i);m_selectedWave=std::clamp(m_selectedWave,0,std::max(0,static_cast<int>(m_asset.waves.size())-1));m_dirty=true;ImGui::PopID();break;}ImGui::PopID();}if(!m_asset.waves.empty()){auto&w=m_asset.waves[static_cast<std::size_t>(std::clamp(m_selectedWave,0,static_cast<int>(m_asset.waves.size())-1))];ImGui::Separator();m_dirty|=ImGui::InputText("Wave Name",&w.name);m_dirty|=ImGui::InputText("Weighted Group",&w.group);m_dirty|=ImGui::DragInt("Spawn Count",&w.count,1,1,10000);m_dirty|=ImGui::DragFloat("Delay Before",&w.delayBefore,.05f,0,3600);m_dirty|=ImGui::DragFloat("Spawn Interval",&w.spawnInterval,.05f,0,3600);m_dirty|=ImGui::DragFloat("Delay After",&w.delayAfter,.05f,0,3600);m_dirty|=ImGui::Checkbox("Wait for Wave Clear",&w.waitForClear);}ImGui::EndTabItem();}
if(ImGui::BeginTabItem("Preview & Debug")){m_dirty|=false;ImGui::DragFloat("Preview Difficulty",&m_previewDifficulty,.05f,0,10);if(ImGui::Button(m_previewPlaying?"Pause Preview":"Play Preview"))m_previewPlaying=!m_previewPlaying;ImGui::SameLine();if(ImGui::Button("Reset Preview"))m_previewTime=0;DrawVolumePreview();int eligible=0,total=0;for(const auto&e:m_asset.entries)if(m_previewDifficulty>=e.minimumDifficulty&&m_previewDifficulty<=e.maximumDifficulty)++eligible;for(const auto&w:m_asset.waves)total+=w.count;ImGui::Text("%d eligible entries | %zu waves | %d planned spawns",eligible,m_asset.waves.size(),total);ImGui::TextDisabled("Runtime events report starts, waves, spawned entities, failures, clears and completion.");ImGui::EndTabItem();}ImGui::EndTabBar();}if(m_dirty)ImGui::TextColored({1.0f,.75f,.2f,1.0f},"Unsaved changes");if(!m_status.empty())ImGui::TextWrapped("%s",m_status.c_str());ImGui::End();return result;}
